<template><div style="padding:20px"><h2>Instagram Font Generator - TOOLBABA</h2><input v-model="input" style="width:100%;padding:12px" placeholder="Apna naam likho" /><div v-for="f in output" :key="f.name" style="margin:8px 0;padding:12px;border:1px solid #ddd;border-radius:8px;display:flex;justify-content:space-between"><b>{{ f.name }}:</b><span>{{ f.text }}</span><button @click="navigator.clipboard.writeText(f.text)">Copy</button></div></div></template><script setup>import { ref, computed } from 'vue'; const input=ref('ToolBaba'); const output=computed(()=>[{name:'Style 1',text:`꧁ ${input.value} ꧂`},{name:'Style 2',text:`★ ${input.value} ★`},{name:'Style 3',text:`🔥 ${input.value} 🔥`},{name:'Style 4',text:`ω ${input.value} ω`},{name:'Style 5',text:`${input.value}™`}])</script>
